<template>
  <section class="effect-picker" aria-label="特效选择">
    <header><div><strong>特效选择</strong><small>{{ activeKind==='text'?'文本特效使用示例气泡预览':activeKind==='interaction'?'双方头像会在独立动画层中互动，不推动消息布局':'屏幕特效直接在演出画布预览' }}</small></div><button type="button" aria-label="重播特效" @click="requestPreview">▶ 预览</button></header>
    <nav v-if="kindCount>1" class="effect-kind-tabs" :style="{'--kind-count':kindCount}"><button v-if="showText" type="button" :class="{active:activeKind==='text'}" @click="activeKind='text'">文本特效</button><button v-if="showScreen" type="button" :class="{active:activeKind==='screen'}" @click="activeKind='screen'">屏幕特效</button><button v-if="showInteraction" type="button" :class="{active:activeKind==='interaction'}" @click="chooseInteractionKind">互动特效</button></nav>
    <div v-if="activeKind==='text'" :key="previewKey" class="effect-preview" :style="previewStyle">
      <i class="effect-preview__screen"></i>
      <div class="effect-preview__message"><span class="effect-preview__avatar">洛</span><div><small>示例角色</small><p><span v-for="(token,index) in previewTokens" :key="index" :class="`preview-token preview-token--${normalizedTextEffect}`">{{ token }}</span></p></div></div>
    </div>
    <div v-if="activeKind==='interaction'" :key="previewKey" class="interaction-preview" :class="[`interaction-preview--${interactionEffect}`,`interaction-preview--reaction-${interactionReaction}`]">
      <span class="interaction-preview__actor interaction-preview__actor--source"><img v-if="sourceAvatar" :src="sourceAvatar" alt="发起角色头像" /><i v-else>{{ sourceName.slice(0,1) }}</i><small>{{ sourceName }}</small></span>
      <span class="interaction-preview__projectile">{{ interactionEmoji || defaultInteractionEmoji }}</span>
      <span class="interaction-preview__actor interaction-preview__actor--target"><img v-if="targetAvatar" :src="targetAvatar" alt="目标角色头像" /><i v-else>{{ targetName.slice(0,1) }}</i><small>{{ targetName }}</small></span>
    </div>

    <div v-if="showText&&activeKind==='text'" class="effect-picker__section"><h4>文字出现动画 <small>采用经过调校的预制节奏</small></h4><div class="effect-card-grid"><button v-for="option in textOptions" :key="option.value" type="button" :class="{active:textEffect===option.value}" @click="chooseText(option.value)"><b>{{ option.glyph }}</b><span>{{ option.label }}</span></button></div></div>
    <div v-if="showScreen&&activeKind==='screen'" class="effect-picker__section"><h4>一、动画底子 <small>选择运动与画面形态</small></h4><div class="effect-card-grid effect-card-grid--screen"><button v-for="option in screenOptions" :key="option.value" type="button" :class="{active:screenEffect===option.value}" @click="chooseScreen(option.value)"><b>{{ option.glyph }}</b><span>{{ option.label }}</span></button></div></div>
	<div v-if="showScreen&&activeKind==='screen'" class="effect-picker__section custom-presets"><h4>我的屏幕特效预设 <small>登录后可在个人中心分类、移动和生成分享码</small></h4><section v-for="group in presetGroups" :key="group.id" class="preset-folder"><strong>{{ group.name }}</strong><div class="effect-card-grid"><button v-for="preset in group.items" :key="preset.id" type="button" @click="applyPreset(preset)"><b>★</b><span>{{ preset.name }}</span></button></div></section><div class="preset-save"><input v-model.trim="presetName" maxlength="60" placeholder="给当前组合命名" @keydown.enter.prevent="savePreset"/><button type="button" :disabled="!presetName" @click="savePreset">保存当前组合</button></div></div>
    <div v-if="showInteraction&&activeKind==='interaction'" class="effect-picker__section"><h4>一、互动方式 <small>选择双方头像的运动和投射物轨迹</small></h4><div class="effect-card-grid"><button v-for="option in interactionOptions" :key="option.value" type="button" :class="{active:interactionEffect===option.value}" @click="chooseInteraction(option.value)"><b>{{ option.glyph }}</b><span>{{ option.label }}</span></button></div></div>
    <div v-if="showInteraction&&activeKind==='interaction'" class="effect-picker__section"><h4>二、目标反应 <small>可以回应、倒下、碎裂、灰化或完全不回应</small></h4><div class="effect-card-grid"><button v-for="option in reactionOptions" :key="option.value" type="button" :class="{active:interactionReaction===option.value}" @click="chooseReaction(option.value)"><b>{{ option.glyph }}</b><span>{{ option.label }}</span></button></div><label class="interaction-emoji"><span>Emoji / 符号</span><n-input :value="interactionEmoji" maxlength="8" :placeholder="`默认 ${defaultInteractionEmoji}`" @update:value="chooseEmoji" /></label></div>
    <div v-if="showInteraction&&activeKind==='interaction'" class="effect-picker__section custom-presets"><h4>我的互动特效预设 <small>创建和调整都在这里完成；登录后可在个人中心整理和分享</small></h4><section v-for="group in interactionPresetGroups" :key="group.id" class="preset-folder"><strong>{{ group.name }}</strong><div class="effect-card-grid"><button v-for="preset in group.items" :key="preset.id" type="button" @click="applyPreset(preset)"><b>★</b><span>{{ preset.name }}</span></button></div></section><div class="preset-save"><input v-model.trim="interactionPresetName" maxlength="60" placeholder="给当前互动命名" @keydown.enter.prevent="saveInteractionPreset"/><button type="button" :disabled="!interactionPresetName||interactionEffect==='none'" @click="saveInteractionPreset">保存互动预设</button></div></div>
    <div v-if="showPersistent" class="effect-picker__section"><h4>持续特效形态</h4><div class="effect-card-grid"><button v-for="option in persistentOptions" :key="option.value" type="button" :class="{active:persistentEffect===option.value}" @click="choosePersistent(option.value)"><b>{{ option.glyph }}</b><span>{{ option.label }}</span></button></div></div>
    <div v-if="(showScreen&&activeKind==='screen')||showPersistent" class="effect-picker__section"><h4>二、预制颜色 <small>只改变颜色，不改变动画</small></h4><div class="picker-palette"><button v-for="option in colorOptions" :key="option.value" type="button" :class="{active:color===option.value}" :aria-label="option.label" @click="chooseColor(option.value)"><i :style="{background:option.swatch||option.hex}"></i><span>{{ option.label }}</span><b v-if="color===option.value">✓</b></button></div></div>
    <div v-if="showParameters&&activeKind==='screen'" class="effect-picker__section effect-parameters">
      <h4>三、播放参数 <small>控制屏幕动画节奏，不改变消息停留时间</small></h4>
      <div>
        <label><span>持续时间</span><n-input-number :value="durationMs" :min="120" :max="10000" :step="50" :show-button="false" @update:value="chooseDuration($event ?? 900)" /><small>ms</small></label>
        <label><span>播放速度</span><n-input-number :value="speedPercent" :min="25" :max="400" :step="5" :show-button="false" @update:value="chooseSpeed($event ?? 100)" /><small>%</small></label>
        <label><span>重复次数</span><n-input-number :value="repeat" :min="1" :max="12" :step="1" :show-button="false" @update:value="chooseRepeat($event ?? 1)" /><small>次</small></label>
      </div>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useEffectPresets, type EffectPreset, type InteractionEffectPresetConfig, type ScreenEffectPresetConfig } from "~/composables/useEffectPresets";
import type { StoryEffectColor, StoryInteractionEffect, StoryInteractionReaction, StoryPersistentEffect, StoryScreenEffect, StoryStreamTokenAnimation } from "~/story/types";

const props=withDefaults(defineProps<{showText?:boolean;showScreen?:boolean;showInteraction?:boolean;showPersistent?:boolean;showParameters?:boolean;textEffect?:"inherit"|StoryStreamTokenAnimation;screenEffect?:StoryScreenEffect;persistentEffect?:StoryPersistentEffect|null;color?:StoryEffectColor;durationMs?:number;speedPercent?:number;repeat?:number;interactionEffect?:"none"|StoryInteractionEffect;interactionReaction?:StoryInteractionReaction;interactionEmoji?:string;sourceName?:string;sourceAvatar?:string;targetName?:string;targetAvatar?:string}>(),{showText:false,showScreen:false,showInteraction:false,showPersistent:false,showParameters:false,textEffect:"inherit",screenEffect:"none",persistentEffect:null,color:"auto",durationMs:900,speedPercent:100,repeat:1,interactionEffect:"none",interactionReaction:"stagger",interactionEmoji:"",sourceName:"发起角色",sourceAvatar:"",targetName:"目标角色",targetAvatar:""});
const emit=defineEmits<{text:["inherit"|StoryStreamTokenAnimation];screen:[StoryScreenEffect];persistent:[StoryPersistentEffect];color:[StoryEffectColor];duration:[number];speed:[number];repeat:[number];previewScreen:[];interaction:["none"|StoryInteractionEffect];reaction:[StoryInteractionReaction];emoji:[string];previewInteraction:[]}>();
const {presets,folders,loadEffectPresets,createEffectPreset}=useEffectPresets();const presetName=ref("");const interactionPresetName=ref("");onMounted(()=>loadEffectPresets());
function groupPresets(kind:EffectPreset["kind"]){const groups=[{id:"",name:"未分类",items:presets.value.filter(item=>item.kind===kind&&!item.folderId)}];for(const folder of folders.value)groups.push({id:folder.id,name:folder.name,items:presets.value.filter(item=>item.kind===kind&&item.folderId===folder.id)});return groups.filter(group=>group.items.length)}
const presetGroups=computed(()=>groupPresets("screen"));const interactionPresetGroups=computed(()=>groupPresets("interaction"));
const previewKey=ref(0);const replay=()=>{previewKey.value+=1};
const kindCount=computed(()=>Number(props.showText)+Number(props.showScreen)+Number(props.showInteraction));
const activeKind=ref<"text"|"screen"|"interaction">(props.showText?"text":props.showScreen?"screen":"interaction");
const previewTokens=["这", "是", "一段", "演出", "预览"];
const normalizedTextEffect=computed(()=>props.textEffect==="inherit"?"rise":props.textEffect);
const textOptions:Array<{label:string;value:"inherit"|StoryStreamTokenAnimation;glyph:string}>=[{label:"跟随全局",value:"inherit",glyph:"全"},{label:"上浮淡入",value:"rise",glyph:"↑"},{label:"淡入",value:"fade",glyph:"◐"},{label:"模糊聚焦",value:"blur",glyph:"◎"},{label:"重击落字",value:"impact",glyph:"↓"},{label:"急促震颤",value:"shake",glyph:"≈"},{label:"幽灵显现",value:"ghost",glyph:"◌"},{label:"无动画",value:"none",glyph:"—"}];
const screenOptions:Array<{label:string;value:StoryScreenEffect;glyph:string}>=[{label:"无屏幕效果",value:"none",glyph:"—"},{label:"轻微震动",value:"shake-light",glyph:"≈"},{label:"强烈冲击",value:"shake-heavy",glyph:"≋"},{label:"中心绽放",value:"glow",glyph:"✦"},{label:"横向光扫",value:"warm-glow",glyph:"→"},{label:"镜头闪切",value:"cold-flash",glyph:"▰"},{label:"瞬间曝光",value:"flash",glyph:"☀"},{label:"故障闪烁",value:"flicker",glyph:"▥"},{label:"边缘冲击",value:"damage",glyph:"◉"},{label:"双重脉冲",value:"heartbeat",glyph:"♥"},{label:"幕布切黑",value:"blackout",glyph:"■"},{label:"雾化漂移",value:"dream",glyph:"≋"},{label:"聚光收束",value:"vignette",glyph:"◍"},{label:"波纹扩散",value:"ripple",glyph:"◎"},{label:"幕布揭示",value:"curtain",glyph:"▐"},{label:"色散错位",value:"chromatic",glyph:"◒"},{label:"镜头推进",value:"zoom-focus",glyph:"⊙"}];
const interactionOptions:Array<{label:string;value:"none"|StoryInteractionEffect;glyph:string}>=[{label:"无互动",value:"none",glyph:"—"},{label:"投掷 Emoji",value:"throw",glyph:"↗"},{label:"贴近爱心",value:"heart",glyph:"♥"},{label:"施放法术",value:"magic",glyph:"✦"},{label:"突然惊吓",value:"surprise",glyph:"!"},{label:"近身冲击",value:"impact",glyph:"✹"},{label:"高速子弹",value:"bullet",glyph:"•"},{label:"飞掷刀刃",value:"blade",glyph:"†"}];
const reactionOptions:Array<{label:string;value:StoryInteractionReaction;glyph:string}>=[{label:"不回应",value:"none",glyph:"…"},{label:"跳起来",value:"bounce",glyph:"↑"},{label:"踉跄",value:"stagger",glyph:"≈"},{label:"晕倒",value:"faint",glyph:"↷"},{label:"碎开",value:"shatter",glyph:"◇"},{label:"灰掉",value:"gray",glyph:"◐"},{label:"贴近回应",value:"affection",glyph:"♥"}];
const interactionEmojiDefaults:Record<StoryInteractionEffect,string>={throw:"🪨",heart:"💗",magic:"✨",surprise:"❗",impact:"💥",bullet:"•",blade:"🗡️"};
const defaultInteractionEmoji=computed(()=>props.interactionEffect==="none"?"":interactionEmojiDefaults[props.interactionEffect]);
const persistentOptions:Array<{label:string;value:StoryPersistentEffect;glyph:string}>=[{label:"边缘警戒",value:"low-health",glyph:"▣"},{label:"暗角侵蚀",value:"curse",glyph:"◉"},{label:"流动雾幕",value:"dream-haze",glyph:"≋"},{label:"断续风暴",value:"storm",glyph:"ϟ"},{label:"呼吸光环",value:"magic-aura",glyph:"◎"}];
const colorOptions:Array<{label:string;value:StoryEffectColor;hex:string;swatch?:string}>=[{label:"自动",value:"auto",hex:"#6bcfc6",swatch:"conic-gradient(#df6070,#d5b34f,#59bf83,#56bec5,#a276d3,#df6070)"},{label:"中性",value:"neutral",hex:"#d9e2df"},{label:"绯红",value:"red",hex:"#df6070"},{label:"橙焰",value:"orange",hex:"#e68a52"},{label:"金辉",value:"gold",hex:"#d5b34f"},{label:"森绿",value:"green",hex:"#59bf83"},{label:"青蓝",value:"cyan",hex:"#56bec5"},{label:"深蓝",value:"blue",hex:"#6595dc"},{label:"幽紫",value:"purple",hex:"#a276d3"},{label:"绯粉",value:"pink",hex:"#d66f9f"}];
const colorHex=computed(()=>colorOptions.find(option=>option.value===props.color)?.hex||colorOptions[0].hex);
const previewDuration=computed(()=>`${Math.max(80,Math.round(props.durationMs*100/Math.max(25,props.speedPercent)))}ms`);
const previewStyle=computed(()=>({'--preview-color':colorHex.value,'--preview-duration':previewDuration.value,'--preview-repeat':String(Math.max(1,props.repeat))}));
function requestPreview(){if(activeKind.value==="text")replay();else if(activeKind.value==="interaction"){replay();emit("previewInteraction")}else emit("previewScreen")}function chooseText(value:"inherit"|StoryStreamTokenAnimation){activeKind.value="text";emit("text",value);replay()}function chooseScreen(value:StoryScreenEffect){activeKind.value="screen";emit("screen",value);emit("previewScreen")}function choosePersistent(value:StoryPersistentEffect){emit("persistent",value);replay()}function chooseColor(value:StoryEffectColor){emit("color",value);if(activeKind.value==="screen")emit("previewScreen");else replay()}function chooseDuration(value:number){emit("duration",Math.round(value));emit("previewScreen")}function chooseSpeed(value:number){emit("speed",Math.round(value));emit("previewScreen")}function chooseRepeat(value:number){emit("repeat",Math.round(value));emit("previewScreen")}
function chooseInteractionKind(){activeKind.value="interaction";replay()}function chooseInteraction(value:"none"|StoryInteractionEffect){activeKind.value="interaction";emit("interaction",value);replay();if(value!=="none")emit("previewInteraction")}function chooseReaction(value:StoryInteractionReaction){emit("reaction",value);replay();if(props.interactionEffect!=="none")emit("previewInteraction")}function chooseEmoji(value:string){emit("emoji",value);replay()}
function applyPreset(preset:EffectPreset){if(preset.kind==="interaction"){const config=preset.config as InteractionEffectPresetConfig;emit("interaction",config.interactionEffect);emit("reaction",config.reaction);emit("emoji",config.emoji);activeKind.value="interaction";replay();emit("previewInteraction");return}const config=preset.config as ScreenEffectPresetConfig;emit("screen",config.screenEffect);emit("color",config.color);emit("duration",config.durationMs);emit("speed",config.speedPercent);emit("repeat",config.repeat);emit("previewScreen")}
async function savePreset(){if(!presetName.value)return;await createEffectPreset(presetName.value,{screenEffect:props.screenEffect,color:props.color,durationMs:props.durationMs,speedPercent:props.speedPercent,repeat:props.repeat});presetName.value=""}
async function saveInteractionPreset(){if(!interactionPresetName.value||props.interactionEffect==="none")return;await createEffectPreset(interactionPresetName.value,{interactionEffect:props.interactionEffect,reaction:props.interactionReaction,emoji:props.interactionEmoji},"","interaction");interactionPresetName.value=""}
</script>

<style scoped>
.effect-picker{display:grid;gap:.8rem;width:min(760px,100%);max-height:min(70vh,680px);overflow:auto;padding:.85rem;border:1px solid var(--control-border);border-radius:15px;background:var(--panel-surface);color:var(--control-text);box-shadow:0 16px 40px #0004}.effect-picker>header{display:flex;align-items:center;justify-content:space-between;gap:1rem}.effect-picker>header div{display:grid}.effect-picker>header small,.effect-picker h4 small{color:var(--muted-text);font-weight:400}.effect-picker>header button{min-height:34px;border:1px solid var(--control-border);background:var(--control-surface);color:var(--control-text)}.effect-preview{position:relative;min-height:132px;overflow:hidden;border:1px solid var(--control-border);border-radius:14px;background:var(--canvas-bg);isolation:isolate}.effect-preview__screen{position:absolute;z-index:-1;inset:0;pointer-events:none}.effect-preview__message{position:absolute;left:50%;bottom:16px;display:flex;align-items:flex-start;gap:9px;width:min(390px,calc(100% - 24px));transform:translateX(-50%)}.effect-preview__avatar{display:grid;width:36px;height:36px;flex:0 0 36px;place-items:center;border:2px solid var(--preview-color);border-radius:50%;background:var(--control-surface)}.effect-preview__message>div{display:grid;gap:3px}.effect-preview__message small{color:var(--preview-color);font-weight:650}.effect-preview__message p{margin:0;border-radius:13px;padding:.65rem .8rem;background:var(--bubble-bg);color:var(--bubble-text)}.preview-token{display:inline-block;animation:.32s ease both}.preview-token:nth-child(2){animation-delay:.08s}.preview-token:nth-child(3){animation-delay:.16s}.preview-token:nth-child(4){animation-delay:.24s}.preview-token:nth-child(5){animation-delay:.32s}.preview-token--fade{animation-name:token-fade}.preview-token--rise{animation-name:token-rise}.preview-token--blur{animation-name:token-blur}.preview-token--impact{animation-name:token-impact}.preview-token--shake{animation-name:token-shake}.preview-token--ghost{animation-name:token-ghost}.effect-picker__section{display:grid;gap:.45rem}.effect-picker h4{margin:0;font-size:.8rem}.effect-card-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(92px,1fr));gap:.42rem}.effect-card-grid button{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:.45rem;min-height:42px;border:1px solid var(--control-border);border-radius:10px;padding:.42rem .55rem;background:var(--control-surface);color:var(--control-text);text-align:left}.effect-card-grid button:hover{background:var(--control-hover)}.effect-card-grid button.active{border-color:var(--focus-color);background:color-mix(in srgb,var(--focus-color) 15%,var(--control-surface));box-shadow:inset 0 0 0 1px var(--focus-color)}.effect-card-grid button b{display:grid;width:24px;height:24px;place-items:center;border-radius:7px;background:var(--soft-surface);font-size:.78rem}.effect-card-grid button span{font-size:.74rem}.picker-palette{display:grid;grid-template-columns:repeat(auto-fit,minmax(76px,1fr));gap:.42rem}.picker-palette button{position:relative;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.4rem;min-height:38px;border:1px solid var(--control-border);border-radius:10px;padding:.38rem .48rem;background:var(--control-surface);color:var(--control-text)}.picker-palette button.active{border-color:var(--focus-color);box-shadow:inset 0 0 0 1px var(--focus-color)}.picker-palette i{width:18px;height:18px;border:1px solid var(--control-border);border-radius:50%}.picker-palette span{font-size:.72rem}.picker-palette b{color:var(--focus-color)}
.effect-preview--glow .effect-preview__screen{animation:bloom var(--preview-duration) var(--preview-repeat);background:radial-gradient(circle,var(--preview-color),transparent 64%)}.effect-preview--warm-glow .effect-preview__screen{animation:sweep var(--preview-duration) var(--preview-repeat);background:linear-gradient(105deg,transparent 20%,var(--preview-color),transparent 80%)}.effect-preview--cold-flash .effect-preview__screen{animation:cut var(--preview-duration) var(--preview-repeat);background:linear-gradient(90deg,transparent,var(--preview-color),transparent)}.effect-preview--flash .effect-preview__screen{animation:flash var(--preview-duration) var(--preview-repeat);background:color-mix(in srgb,var(--preview-color) 70%,white)}.effect-preview--flicker .effect-preview__screen{animation:glitch var(--preview-duration) steps(1) var(--preview-repeat);background:repeating-linear-gradient(0deg,transparent 0 5px,var(--preview-color) 6px 7px)}.effect-preview--damage .effect-preview__screen,.effect-preview--heartbeat .effect-preview__screen{animation:pulse var(--preview-duration) var(--preview-repeat);background:radial-gradient(circle,transparent 30%,var(--preview-color))}.effect-preview--blackout .effect-preview__screen{animation:flash var(--preview-duration) var(--preview-repeat);background:#000}.effect-preview--dream .effect-preview__screen{animation:drift var(--preview-duration) var(--preview-repeat);background:linear-gradient(125deg,var(--preview-color),transparent 50%,var(--preview-color))}.effect-preview--vignette .effect-preview__screen{animation:flash var(--preview-duration) var(--preview-repeat);background:radial-gradient(circle,transparent 25%,color-mix(in srgb,var(--preview-color) 35%,#000c))}.effect-preview--shake-light .effect-preview__message{animation:shake var(--preview-duration) var(--preview-repeat)}.effect-preview--shake-heavy .effect-preview__message{animation:shake-heavy var(--preview-duration) var(--preview-repeat)}.effect-preview--persistent-low-health{box-shadow:inset 0 0 16px var(--preview-color)}.effect-preview--persistent-curse .effect-preview__screen{background:radial-gradient(circle,transparent 30%,color-mix(in srgb,var(--preview-color) 65%,#0009))}.effect-preview--persistent-dream-haze .effect-preview__screen{animation:drift var(--preview-duration) infinite;background:linear-gradient(125deg,var(--preview-color),transparent 60%);opacity:.35}.effect-preview--persistent-storm .effect-preview__screen{animation:glitch var(--preview-duration) steps(1) infinite;background:repeating-linear-gradient(170deg,transparent 0 18px,var(--preview-color) 19px 20px)}.effect-preview--persistent-magic-aura .effect-preview__screen{animation:bloom var(--preview-duration) infinite;background:radial-gradient(circle,var(--preview-color),transparent 65%);opacity:.4}
.effect-parameters>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.5rem}.effect-parameters label{display:grid;grid-template-columns:1fr minmax(72px,110px) auto;align-items:center;gap:.4rem;border:1px solid var(--control-border);border-radius:10px;padding:.45rem .55rem;background:var(--control-surface)}.effect-parameters label>span{font-size:.74rem}.effect-parameters label>small{color:var(--muted-text)}
